import csv
import io
from datetime import datetime

SAMPLE = {"habit": "walk", "value": 30, "note": "sample entry"}


def main(input_data):
    d = input_data if isinstance(input_data, dict) and input_data.get("habit") else SAMPLE
    habit = str(d["habit"]).strip().lower()[:50]
    if not habit:
        raise ValueError("habit is empty")
    try:
        value = float(d.get("value", 1))
    except (TypeError, ValueError):
        raise ValueError("value must be a number")
    now = datetime.now().astimezone()
    out = io.StringIO()
    csv.writer(out, lineterminator="\n").writerow(
        [now.strftime("%Y-%m-%d"), now.strftime("%H:%M"), habit, value, str(d.get("note", ""))[:200]])
    return {"line": out.getvalue(), "habit": habit}
